import { Schema as S } from "effect";
import type { Command } from "foldkit";
import { Submodel } from "foldkit";
import type { Html } from "foldkit/html";

import * as Breadcrumb from "../../ui/breadcrumb";

// MODEL

export const Model = S.Struct({});
export type Model = typeof Model.Type;

// MESSAGE

export const Message = S.Never;
export type Message = typeof Message.Type;

// INIT

export const init = (): readonly [
  Model,
  readonly Command.Command<Message>[],
] => [{}, []];

// UPDATE

export const update = (
  model: Model,
  _message: Message
): readonly [Model, readonly Command.Command<Message>[]] => [model, []];

// VIEW

export const view = Submodel.defineView<Model, Message>(
  (): Html =>
    Breadcrumb.rootView<Message>({
      children: [
        Breadcrumb.listView<Message>({
          children: [
            Breadcrumb.itemView<Message>({
              children: [
                Breadcrumb.linkView<Message>({ href: "/", children: ["Home"] }),
              ],
            }),
            Breadcrumb.separatorView<Message>(),
            Breadcrumb.itemView<Message>({
              children: [Breadcrumb.ellipsisView<Message>()],
            }),
            Breadcrumb.separatorView<Message>(),
            Breadcrumb.itemView<Message>({
              children: [
                Breadcrumb.linkView<Message>({
                  href: "/components",
                  children: ["Components"],
                }),
              ],
            }),
            Breadcrumb.separatorView<Message>(),
            Breadcrumb.itemView<Message>({
              children: [
                Breadcrumb.pageView<Message>({ children: ["Breadcrumb"] }),
              ],
            }),
          ],
        }),
      ],
    })
);

import { Runtime } from "foldkit";

import { Model, init, update, view } from "./main";

const program = Runtime.makeApplication({
  Model,
  init,
  update,
  view: (model) => ({ title: "Breadcrumb Collapsed", body: view(model) }),
  container: document.querySelector("#root"),
});

Runtime.run(program);

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import { init, update, view } from "./main";

describe("breadcrumb-collapsed example", () => {
  test("renders the shadcn Breadcrumb Collapsed example", () => {
    const [model] = init();

    Scene.scene(
      { update, view },
      Scene.with(model),
      Scene.expect(Scene.role("navigation", { name: "breadcrumb" })).toExist(),
      Scene.expect(Scene.role("img", { name: "More" })).toExist(),
      Scene.expect(Scene.role("img", { name: "More" })).not.toHaveHandler(
        "click"
      )
    );
  });
});
